    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int r = Integer.parseInt(st.nextToken());
        String[] recipes = new String[r];
        List<List<String>> ingredients = new ArrayList<>();
        for (int i = 0; i < r; i++) {
            recipes[i] = st.nextToken();
            int m = Integer.parseInt(st.nextToken());
            List<String> ing = new ArrayList<>();
            for (int j = 0; j < m; j++) ing.add(st.nextToken());
            ingredients.add(ing);
        }
        int s = Integer.parseInt(st.nextToken());
        String[] supplies = new String[s];
        for (int i = 0; i < s; i++) supplies[i] = st.nextToken();
        List<String> res = new ArrayList<>(findRecipes(recipes, ingredients, supplies));
        Collections.sort(res);
        System.out.println(res.isEmpty() ? "-1" : String.join(" ", res));
    }
}
